    els.agentGroups.innerHTML = Object.keys(groups).map(function (group) {
      return '<div class="user-agent-group">' +
        '<div class="user-agent-group-title">' + escapeHtml(group) + '</div>' +
        groups[group].map(renderAgentCard).join('') +
        '</div>';
    }).join('') || '<div class="user-empty">没有找到匹配的智能体</div>';
  }

  function renderAgentCard(agent) {
    var active = agent.id === state.activeAgentId ? ' active' : '';
    var fav = state.favorites.indexOf(agent.id) >= 0 ? '已收藏' : '收藏';
    var statusClass = agent.status === '维护中' ? 'tag-maintain' : 'tag-published';
    return '<button type="button" class="user-agent-card' + active + '" data-agent-id="' + agent.id + '">' +
      '<span class="user-agent-avatar">' + escapeHtml(shortName(agent.name).slice(0, 2)) + '</span>' +
      '<span class="user-agent-card-main">' +
        '<strong>' + escapeHtml(agent.name) + '</strong>' +
        '<small>' + escapeHtml(agent.scenarios.slice(0, 2).join(' / ')) + '</small>' +
      '</span>' +
      '<span class="tag ' + statusClass + '">' + escapeHtml(agent.status) + '</span>' +
      '<span class="user-agent-fav">' + fav + '</span>' +
    '</button>';
  }

  function renderActiveAgent() {
    var agent = currentAgent();
    els.activeAgentName.textContent = agent.name;
    els.activeAgentIntro.textContent = agent.intro;
    document.querySelectorAll('[data-agent-name]').forEach(function (node) { node.textContent = agent.name; });
    els.modelSelect.value = agent.model + ' 模型';
    els.btnFavorite.textContent = state.favorites.indexOf(agent.id) >= 0 ? '已收藏' : '收藏';
    els.serviceStatus.innerHTML = '<span class="tag ' + (agent.status === '维护中' ? 'tag-maintain' : 'tag-published') + '">' + agent.status + '</span>' +
      '<span>' + escapeHtml(agent.status === '维护中' ? '当前智能体正在维护，可查看历史资产或申请通知。' : '知识库已同步，生成失败可重试或转人工。') + '</span>';
    els.scenarioSelect.innerHTML = agent.scenarios.map(function (item) {
      return '<option>' + escapeHtml(item) + '</option>';
    }).join('');
    els.promptSuggestions.innerHTML = agent.examples.map(function (example) {
      return '<button type="button" data-prompt="' + escapeHtml(example) + '">' + escapeHtml(example) + '</button>';
    }).join('');
    els.agentDetail.innerHTML = renderDetail(agent);
    renderAssets();
    renderFeedback();
    renderAgents();
  }

  function renderDetail(agent) {
    return '<div class="user-agent-detail-card">' +
      '<div class="user-section-title"><strong>能力说明</strong><span>' + escapeHtml(agent.version) + ' · ' + escapeHtml(agent.model) + '</span></div>' +
      '<p>' + escapeHtml(agent.intro) + '</p>' +
      '<div class="user-mini-tags">' + agent.tags.map(function (tag) { return '<span>' + escapeHtml(tag) + '</span>'; }).join('') + '</div>' +
      '<div class="user-detail-block"><strong>适用场景</strong><ul>' + agent.scenarios.map(function (item) { return '<li>' + escapeHtml(item) + '</li>'; }).join('') + '</ul></div>' +
      '<div class="user-detail-block"><strong>输入要求</strong><ul>' + agent.inputs.map(function (item) { return '<li>' + escapeHtml(item) + '</li>'; }).join('') + '</ul></div>' +
      '<div class="user-detail-block"><strong>知识来源</strong><ul>' + agent.sources.map(function (item) { return '<li>' + escapeHtml(item) + '</li>'; }).join('') + '</ul></div>' +
      '</div>';
  }

  function renderAssets() {
    var list = state.assets.filter(function (asset) {
      return asset.agentId === state.activeAgentId || state.activeAgentId === 'agt_ocean_ops';
    });
    els.assetList.innerHTML = list.map(function (asset) {
      var status = asset.status === 'ready' ? '可下载' : '需恢复';
      var tag = asset.status === 'ready' ? 'tag-ok' : 'tag-warn';
      var action = asset.status === 'ready'
        ? '<button type="button" class="btn btn-sm" data-download-asset="' + asset.id + '">下载</button>'
        : '<button type="button" class="btn btn-sm" data-recover-asset="' + asset.id + '">重试生成</button>';
      return '<div class="user-asset-item">' +
        '<div><strong>' + escapeHtml(asset.name) + '</strong><span>' + escapeHtml(asset.type) + ' · ' + escapeHtml(asset.time) + ' · ' + escapeHtml(asset.version) + '</span></div>' +
        '<span class="tag ' + tag + '">' + status + '</span>' +
        action +
      '</div>';
    }).join('') || '<div class="user-empty">当前智能体还没有生成记录</div>';
  }

  function renderFeedback() {
    els.feedbackList.innerHTML = state.feedbacks.map(function (item) {
      return '<div class="user-feedback-item">' +
        '<strong>' + escapeHtml(item.id) + ' · ' + escapeHtml(item.title) + '</strong>' +
        '<span>' + escapeHtml(item.status) + ' · ' + escapeHtml(item.meta) + '</span>' +
      '</div>';
    }).join('') || '<div class="user-empty">暂无反馈单</div>';
  }

  function renderMessages() {
    var list = state.messages.filter(function (msg) { return msg.type === messageTab; });
    els.messageList.innerHTML = list.map(function (msg) {
      return '<div class="drawer-item unread">' +
        '<div class="di-title">' + escapeHtml(msg.title) + '</div>' +
        '<div class="di-meta">' + escapeHtml(msg.meta) + '</div>' +
      '</div>';
    }).join('');
    els.messageCount.textContent = String(state.messages.filter(function (msg) { return msg.type === 'todo'; }).length);
  }

  function addRecent(id) {
    state.recent = [id].concat(state.recent.filter(function (x) { return x !== id; })).slice(0, 5);
  }

  function selectAgent(id) {
    state.activeAgentId = id;
    addRecent(id);
    saveState();
    renderActiveAgent();
    toast('已切换到 ' + currentAgent().name);
  }

  function toggleFavorite() {
    var id = state.activeAgentId;
    if (state.favorites.indexOf(id) >= 0) {
      state.favorites = state.favorites.filter(function (x) { return x !== id; });
    } else {
      state.favorites.unshift(id);
    }
    saveState();
    renderActiveAgent();
  }

  function appendMessage(html) {
    els.chatMsgs.insertAdjacentHTML('beforeend', html);
    els.chatMsgs.scrollTop = els.chatMsgs.scrollHeight;
  }

  function buildProgress(agent, prompt, skillNames) {
    var output = els.outputSelect.value;
    return '<div class="chat-msg-reply user-rich-reply">' +
      '<div class="user-process-list">' +
        '<div><span class="tag tag-ok">意图识别</span><strong>' + escapeHtml(els.scenarioSelect.value) + '</strong></div>' +
        '<div><span class="tag tag-ok">知识检索</span><strong>' + escapeHtml(agent.sources.slice(0, 2).join('、')) + '</strong></div>' +
        '<div><span class="tag tag-info">工具调用</span><strong>' + escapeHtml(skillNames.length ? skillNames.join('、') : agent.tags[0]) + '</strong></div>' +
        '<div><span class="tag tag-pending">文件生成</span><strong>' + escapeHtml(output) + ' · 已生成版本 v1</strong></div>' +
      '</div>' +
      '<p>已根据“' + escapeHtml(prompt) + '”整理结果。回答会保留引用来源，并同步到“我的资产”。</p>' +
      '<div class="user-source-box"><strong>引用来源</strong><button type="button" class="btn btn-sm" data-view-source>查看原文</button><span>' + escapeHtml(agent.sources[0]) + ' · 第 12-18 条</span></div>' +
      '<div class="user-recover-box">' +
        '<strong>可恢复异常示例</strong><span>如文件 ID 找不到或下载失败，可直接重试生成、重新下载或联系支持。</span>' +
        '<div><button type="button" class="btn btn-sm" data-retry-generate>重试生成</button><button type="button" class="btn btn-sm" data-contact-support>联系支持</button></div>' +
      '</div>' +
      '<div class="user-result-actions">' +
        '<button type="button" class="btn btn-sm" data-copy-answer>复制</button>' +
        '<button type="button" class="btn btn-sm" data-edit-answer>编辑</button>' +
        '<button type="button" class="btn btn-sm" data-regenerate>重新生成</button>' +
        '<button type="button" class="btn btn-sm" data-open-feedback>反馈</button>' +
      '</div>' +
    '</div>';
  }

  function sendChat() {
    var text = els.chatInput.value.trim();
    if (!text) return;
    var agent = currentAgent();
    if (agent.status === '维护中') {
      toast('该智能体维护中，可先查看资产或订阅通知');
      return;
    }
    var skillNames = [];
    if (opts.sessionSkills && typeof opts.sessionSkills.getActiveNames === 'function') {
      skillNames = opts.sessionSkills.getActiveNames();
    }
    appendMessage('<div class="chat-msg-user">' + escapeHtml(text) + '</div>');
    appendMessage(buildProgress(agent, text, skillNames));
    var assetId = 'asset_' + Date.now();
    state.assets.unshift({
      id: assetId,
      name: agent.name + '生成记录-' + els.outputSelect.value + '.docx',
      type: els.outputSelect.value,
      status: 'ready',
      agentId: agent.id,
      time: '刚刚',
      version: 'v1'
    });
    state.messages.unshift({ id: 'msg_' + assetId, type: 'todo', title: agent.name + '已完成生成', meta: '刚刚 · 可在我的资产中查看' });
    addRecent(agent.id);
    saveState();
    renderAssets();
    renderMessages();
    els.chatInput.value = '';
    if (global.Proto && typeof global.Proto.recordSessionUsage === 'function') global.Proto.recordSessionUsage(agent.id);
  }

  function openFeedback(title) {
    pendingFeedback = title || '用户反馈';
    els.feedbackText.value = '';
    els.feedbackReasons.querySelectorAll('input').forEach(function (input) { input.checked = false; });
    els.feedbackModal.classList.remove('hidden');
  }

  function closeFeedback() {
    els.feedbackModal.classList.add('hidden');
  }

  function submitFeedback() {
    var reasons = Array.prototype.slice.call(els.feedbackReasons.querySelectorAll('input:checked')).map(function (input) {
      return input.value;
    });
    var id = 'FB-' + String(2407 + state.feedbacks.length);
    state.feedbacks.unshift({
      id: id,
      title: reasons[0] || pendingFeedback || '用户反馈',
      status: '已提交',
      meta: '运营受理中 · 可在消息中心追踪'
    });
    state.messages.unshift({ id: 'msg_' + id, type: 'todo', title: '反馈单 ' + id + ' 已创建', meta: '刚刚 · 处理状态会持续通知' });
    saveState();
    renderFeedback();
    renderMessages();
    closeFeedback();
    showPanel('feedback');
    toast('反馈单已创建，可追踪处理进度');
  }

  function requestExpert() {
    var id = 'EX-' + (320 + state.feedbacks.length);
    state.feedbacks.unshift({
      id: id,
      title: currentAgent().name + '专家复核',
      status: '待补充材料',
      meta: '预计 1 个工作日响应 · 仅展示用户进度'
    });
    state.messages.unshift({ id: 'msg_' + id, type: 'todo', title: '专家复核申请已提交', meta: '请补充材料后等待专家回复' });
    saveState();
    renderFeedback();
    renderMessages();
    showPanel('feedback');
    toast('专家复核申请已提交');
  }

  function showPanel(name) {
    els.sideTabs.querySelectorAll('button').forEach(function (btn) {
      btn.classList.toggle('active', btn.dataset.panel === name);
    });
    document.querySelectorAll('.user-side-section').forEach(function (panel) {
      panel.classList.toggle('active', panel.id === 'panel-' + name);
    });
  }

  function recoverAsset(id) {
    state.assets = state.assets.map(function (asset) {
      if (asset.id === id) return Object.assign({}, asset, { status: 'ready', time: '刚刚', version: 'v2' });
      return asset;
    });
    state.messages.unshift({ id: 'msg_recover_' + id, type: 'todo', title: '文件已重新生成', meta: '刚刚 · 下载失败已恢复' });
    saveState();
    renderAssets();
    renderMessages();
    toast('文件已重新生成，可下载');
  }

  function mockUpload() {
    var name = currentAgent().name + ' 示例材料.docx';
    state.uploads.unshift(name);
    saveState();
    els.uploadHint.textContent = '已添加：' + name;
    toast('示例材料已加入本次会话');
  }

  function bindEvents() {
    els.agentSearch.addEventListener('input', renderAgents);
    els.agentTabs.addEventListener('click', function (event) {
      var btn = event.target.closest('button[data-filter]');
      if (!btn) return;
      els.agentTabs.querySelectorAll('button').forEach(function (node) { node.classList.remove('active'); });
      btn.classList.add('active');
      renderAgents();
    });
    els.agentGroups.addEventListener('click', function (event) {
      var card = event.target.closest('[data-agent-id]');
      if (card) selectAgent(card.dataset.agentId);
    });
    els.btnFavorite.addEventListener('click', toggleFavorite);
    els.chatSend.addEventListener('click', sendChat);
    els.chatInput.addEventListener('keydown', function (event) {
      if (event.key === 'Enter' && !event.shiftKey) {
        event.preventDefault();
        sendChat();
      }
    });
    els.promptSuggestions.addEventListener('click', function (event) {
      var btn = event.target.closest('[data-prompt]');
      if (!btn) return;
      els.chatInput.value = btn.dataset.prompt;
      els.chatInput.focus();
    });
    els.sideTabs.addEventListener('click', function (event) {
      var btn = event.target.closest('button[data-panel]');
      if (btn) showPanel(btn.dataset.panel);
    });
    els.assetList.addEventListener('click', function (event) {
      var recover = event.target.closest('[data-recover-asset]');
      var download = event.target.closest('[data-download-asset]');
      if (recover) recoverAsset(recover.dataset.recoverAsset);
      if (download) toast('开始下载文件');
    });
    els.chatMsgs.addEventListener('click', function (event) {
      if (event.target.closest('[data-open-feedback]')) openFeedback('回答质量反馈');
      if (event.target.closest('[data-retry-generate]') || event.target.closest('[data-regenerate]')) toast('已重新发起生成任务');
      if (event.target.closest('[data-contact-support]')) openFeedback('联系支持');
      if (event.target.closest('[data-view-source]')) toast('已打开引用原文预览');
      if (event.target.closest('[data-copy-answer]')) toast('回答已复制');
      if (event.target.closest('[data-edit-answer]')) toast('已进入结果编辑状态');
    });
    els.btnMessages.addEventListener('click', function () {
      els.messageDrawer.classList.remove('hidden');
      els.messageDrawer.setAttribute('aria-hidden', 'false');
    });
    els.btnCloseMessages.addEventListener('click', function () {
      els.messageDrawer.classList.add('hidden');
      els.messageDrawer.setAttribute('aria-hidden', 'true');
    });
    els.messageTabs.addEventListener('click', function (event) {
      var btn = event.target.closest('button[data-message-tab]');
      if (!btn) return;
      messageTab = btn.dataset.messageTab;
      els.messageTabs.querySelectorAll('button').forEach(function (node) { node.classList.remove('active'); });
      btn.classList.add('active');
      renderMessages();
    });
    els.btnMockUpload.addEventListener('click', mockUpload);
    els.btnRequestExpert.addEventListener('click', requestExpert);
    els.btnPermission.addEventListener('click', function () {
      state.messages.unshift({ id: 'msg_perm_' + Date.now(), type: 'todo', title: '权限申请已提交', meta: '当前仅申请用户可见范围，不暴露后台权限表' });
      saveState();
      renderMessages();
      toast('权限申请已提交');
    });
    els.btnCloseFeedback.addEventListener('click', closeFeedback);
    els.btnCancelFeedback.addEventListener('click', closeFeedback);
    els.btnSubmitFeedback.addEventListener('click', submitFeedback);
  }

  var opts = {};

  function init(options) {
    opts = options || {};
    state = loadState();
    els = {
      agentSearch: document.getElementById('agentSearch'),
      agentTabs: document.getElementById('agentTabs'),
      agentGroups: document.getElementById('agentGroups'),
      activeAgentName: document.getElementById('activeAgentName'),
      activeAgentIntro: document.getElementById('activeAgentIntro'),
      modelSelect: document.getElementById('modelSelect'),
      btnFavorite: document.getElementById('btnFavorite'),
      serviceStatus: document.getElementById('serviceStatus'),
      scenarioSelect: document.getElementById('scenarioSelect'),
      knowledgeSelect: document.getElementById('knowledgeSelect'),
      outputSelect: document.getElementById('outputSelect'),
      uploadHint: document.getElementById('uploadHint'),
      btnMockUpload: document.getElementById('btnMockUpload'),
      promptSuggestions: document.getElementById('promptSuggestions'),
      chatMsgs: document.getElementById('chatMsgs'),
      chatInput: document.getElementById('chatInput'),
      chatSend: document.getElementById('chatSend'),
      sideTabs: document.getElementById('sideTabs'),
      agentDetail: document.getElementById('agentDetail'),
      assetList: document.getElementById('assetList'),
      feedbackList: document.getElementById('feedbackList'),
      btnRequestExpert: document.getElementById('btnRequestExpert'),
      btnMessages: document.getElementById('btnMessages'),
      messageDrawer: document.getElementById('userMessageDrawer'),
      btnCloseMessages: document.getElementById('btnCloseMessages'),
      messageTabs: document.getElementById('messageTabs'),
      messageList: document.getElementById('messageList'),
      messageCount: document.getElementById('messageCount'),
      btnPermission: document.getElementById('btnPermission'),
      feedbackModal: document.getElementById('feedbackModal'),
      btnCloseFeedback: document.getElementById('btnCloseFeedback'),
      btnCancelFeedback: document.getElementById('btnCancelFeedback'),
      btnSubmitFeedback: document.getElementById('btnSubmitFeedback'),
      feedbackReasons: document.getElementById('feedbackReasons'),
      feedbackText: document.getElementById('feedbackText')
    };
    bindEvents();
    renderActiveAgent();
    renderMessages();
  }

  global.UserChatPortal = {
    init: init,
    getState: function () { return state; },
    getAgents: function () { return AGENTS.slice(); }
  };
})(window);

